  end if;
  insert into public.class_lesson_content (session_id, event_type, status, blocks, updated_at)
    values ('97d1f3ec-d96d-4ce3-bc78-e7ad970fe50f', 'lesson', 'published', $j$[{"kind": "recap", "title": "Từ Buổi 06 sang Buổi 07", "steps": [{"label": "Đã có (Buổi 01–06)", "items": ["Bản đồ nốt C–Am, ba vùng cần đàn.", "Bass theo hợp âm: gốc hoặc quãng 5; nối nốt bằng gảy lại · trượt · luyến.", "Ba lớp: giai điệu › bass › lót."]}, {"label": "Buổi 07 thêm", "items": ["Bản đồ G–Em: cùng bộ nốt với C–Am, chỉ đổi Fa thành Fa♯.", "Vận dụng vào Thành Phố Buồn giọng Em: chọn vị trí giai điệu, chọn bass theo hợp âm, tính xếp ngón."]}], "message": "Buổi 07 không có kỹ thuật mới. Bạn dùng lại những gì đã học ở một giọng mới, để chuẩn bị tự chuyển soạn ở Buổi 08."}, {"kind": "objectives", "title": "Cuối buổi, bạn làm được", "items": ["Nói được G trưởng và Mi thứ (Em) dùng chung một bộ nốt, và chỉ ra Fa♯ khác Fa của C–Am ở chỗ nào.", "Tìm đúng 7 nốt G–Em ở đầu cần (ngăn 0–4) và chơi được âm giai trong vùng đó.", "Chọn nốt Bass (gốc hoặc quãng 5) cho các hợp âm Em, G, Bm, Am, D, C.", "Làm thử trên giấy một đoạn ngắn: giai điệu → bass → một nốt lót, và giải thích vì sao chọn như vậy.", "⭐ QUAN TRỌNG NHẤT — Nhìn thấy Fa♯ thì không chơi Fa tự nhiên; giai điệu và bass vẫn phải vững trước khi thêm lót."]}, {"kind": "note", "title": "Nhịp 1 · Khám phá bản đồ G–Em", "text": "G trưởng và Mi thứ (Em) là một cặp, giống như C trưởng và La thứ (Am) mà bạn đã học. Cặp này dùng chung 7 nốt: Sol – La – Si – Đô – Rê – Mi – Fa♯. So với C–Am chỉ có MỘT thay đổi: nốt Fa trở thành Fa♯. Sol là nốt trụ của G; Mi là nốt trụ của Em. Kết thúc nhịp: Bài trả 7.1 (trắc nghiệm)."}, {"kind": "fretboard", "title": "Bản đồ nốt G–Em", "lead": "7 nốt · G – A – B – C – D – E – F♯ (Sol – La – Si – Đô – Rê – Mi – Fa♯). Ở đầu cần (ngăn 0–4) đủ cả 6 dây.", "frets": 5, "zones": [{"no": 1, "label": "Vùng đầu cần", "fromFret": 0, "toFret": 4, "strings": [1, 6], "hint": "ngăn 0–4, dùng cả 6 dây. Vùng của bài Thành Phố Buồn giọng Em.", "color": "#4338CA"}], "dots": [{"string": 1, "fret": 0, "name": "E", "nameVi": "Mi", "zone": 1, "root": true}, {"string": 1, "fret": 2, "name": "F♯", "nameVi": "Fa♯", "zone": 1, "root": false}, {"string": 1, "fret": 3, "name": "G", "nameVi": "Sol", "zone": 1, "root": true}, {"string": 2, "fret": 0, "name": "B", "nameVi": "Si", "zone": 1, "root": false}, {"string": 2, "fret": 1, "name": "C", "nameVi": "Đô", "zone": 1, "root": false}, {"string": 2, "fret": 3, "name": "D", "nameVi": "Rê", "zone": 1, "root": false}, {"string": 3, "fret": 0, "name": "G", "nameVi": "Sol", "zone": 1, "root": true}, {"string": 3, "fret": 2, "name": "A", "nameVi": "La", "zone": 1, "root": false}, {"string": 3, "fret": 4, "name": "B", "nameVi": "Si", "zone": 1, "root": false}, {"string": 4, "fret": 0, "name": "D", "nameVi": "Rê", "zone": 1, "root": false}, {"string": 4, "fret": 2, "name": "E", "nameVi": "Mi", "zone": 1, "root": true}, {"string": 4, "fret": 4, "name": "F♯", "nameVi": "Fa♯", "zone": 1, "root": false}, {"string": 5, "fret": 0, "name": "A", "nameVi": "La", "zone": 1, "root": false}, {"string": 5, "fret": 2, "name": "B", "nameVi": "Si", "zone": 1, "root": false}, {"string": 5, "fret": 3, "name": "C", "nameVi": "Đô", "zone": 1, "root": false}, {"string": 6, "fret": 0, "name": "E", "nameVi": "Mi", "zone": 1, "root": true}, {"string": 6, "fret": 2, "name": "F♯", "nameVi": "Fa♯", "zone": 1, "root": false}, {"string": 6, "fret": 3, "name": "G", "nameVi": "Sol", "zone": 1, "root": true}], "legend": ["G = Sol", "A = La", "B = Si", "C = Đô", "D = Rê", "E = Mi", "F♯ = Fa♯ (thay cho Fa của C–Am)", "nốt tô đậm = hai nốt trụ: Sol (G) và Mi (E)"]}, {"kind": "study", "title": "So sánh C–Am với G–Em", "blocks": [{"b": "table", "rows": [["", "C–Am (Buổi 01–06)", "G–Em (Buổi 07)"], ["7 nốt", "Đô – Rê – Mi – Fa – Sol – La – Si", "Sol – La – Si – Đô – Rê – Mi – Fa♯"], ["Nốt trụ", "Đô (C) và La (A)", "Sol (G) và Mi (E)"], ["Khác nhau", "Có Fa (tự nhiên)", "Có Fa♯ — thay cho Fa"], ["Ở đầu cần", "Fa ở dây 1 ngăn 1, dây 4 ngăn 3, dây 6 ngăn 1", "Fa♯ ở dây 1 ngăn 2, dây 4 ngăn 4, dây 6 ngăn 2"]]}, {"b": "callout", "label": "LỖI DỄ MẮC", "text": "Nhầm Fa♯ với Fa tự nhiên. Trong G–Em, mọi nốt Fa đều phải bấm thành Fa♯ (cao hơn Fa một ngăn). Đây là nốt có dấu ♯ ở đầu khuông, bạn đã gặp cách tìm ♯ ở Buổi 04."}]}, {"kind": "score", "title": "Âm giai G–Em ở đầu cần", "subtitle": "Bài tập 01", "lead": "Một hơi từ Rê (dây 4 buông) lên Sol cao rồi xuống lại. Bấm từng nốt và nói tên nốt thành tiếng; gặp Fa♯ thì nói to.", "tex": "\\ts 4 4\n.\n0.4.4 2.4.4 4.4.4 0.3.4 |\n2.3.4 0.2.4 1.2.4 3.2.4 |\n0.1.4 2.1.4 3.1.2 |\n3.1.4 2.1.4 0.1.4 3.2.4 |\n1.2.4 0.2.4 2.3.4 0.3.4 |\n4.4.4 2.4.4 0.4.2", "tempo": "Tempo: ♩ = 60", "marks": [{"at": "Ô 1", "text": "Rê – Mi – Fa♯ – Sol: Fa♯ ở dây 4 ngăn 4"}, {"at": "Ô 3", "text": "Fa♯ ở dây 1 ngăn 2"}], "guidance": ["Đi lên rồi đi xuống, chậm và đều.", "Nói tên nốt khi bấm: gặp Fa♯ không được chơi thành Fa."]}, {"id": "7.1", "kind": "checkpoint", "title": "Bài trả 7.1 — G–Em khác C–Am ở đâu?", "accepts": ["quiz"], "required": true, "quiz": {"mode": "single", "question": "So với bộ nốt C–Am, bộ nốt G–Em khác ở điểm nào?", "options": [{"id": "a", "text": "Không có nốt nào khác."}, {"id": "b", "text": "Fa của C–Am trở thành Fa♯ trong G–Em."}, {"id": "c", "text": "Si của C–Am trở thành Si♭ trong G–Em."}, {"id": "d", "text": "Sol của C–Am trở thành Sol♯ trong G–Em."}], "hint": "Hai giọng chỉ khác nhau đúng một nốt: Fa → Fa♯."}}, {"kind": "note", "title": "Nhịp 2 · Vận dụng Melody và Bass", "text": "Bây giờ dùng G–Em vào một bài thật: Thành Phố Buồn giọng Em (cùng giai điệu bạn đã biết, nhưng hạ xuống giọng Em để nằm gọn ở đầu cần). Làm ba việc theo thứ tự: nhìn vị trí giai điệu, chọn bass theo hợp âm, rồi kiểm tra xem tay trái có chơi được cả hai không. Khi thêm bass mà vướng, quay lại sửa cách xếp ngón của giai điệu, đừng giữ nguyên. Kết thúc nhịp: Bài trả 7.2 (trắc nghiệm)."}, {"kind": "score", "title": "Thành Phố Buồn giọng Em — ô 1–5", "subtitle": "Giai điệu + khung hợp âm", "lead": "Giai điệu ô 1–5, giọng Em (ô 1 là ô lấy đà). Khung hợp âm lấy từ bản hợp âm đã duyệt trong Thư viện Class; ô có hai hợp âm thì đổi theo thứ tự ghi.", "tex": "\\ts 4 4\n\\lyrics \"Thành phố nào _ Nhớ không em _ Nơi chúng mình tìm phút êm đềm Thành phố nào vừa đi đã mỏi _ _ Đường quanh co quyện gốc thông _ già _ Chiều đan tay nghe nắng chan _ hòa Nắng hôn nhẹ làm hồng môi em Mắt em buồn trong sương chiều anh thấy đẹp hơn Một sáng nhau Rồi từ đó _ vì cách xa _ duyên tình thêm nhạt nhòa Rồi từ đó _ trốn phong ba _ em làm dâu nhà người Âm thầm anh tiếc thương đời Đau buồn em khóc chia phôi Anh về gom góp kỷ niệm tìm vui Thành phố buồn _ lắm tơ vương _ cơn gió chiều lạnh buốt tâm hồn và con đường ngày xưa lá đổ _ _ Giờ không em sỏi đá u _ buồn _ Giờ không em hoang vắng phố _ phường Tiếng chuông chiều chầm chậm thê lương tiễn đưa người quên núi đồi quên cả tình yêu\"\n.\nr.8{tu 3} 2.4.8{tu 3} 0.2.8{tu 3} |\n\\ro 2.4.4 2.4{t}.8{tu 3} 0.2.8{tu 3} 2.3.8{tu 3} 0.3.4 0.3{t}.8{tu 3} 0.4.8{tu 3} 2.4.8{tu 3} |\n2.5.4 2.5.8{tu 3} 2.3.8{tu 3} 0.3.8{tu 3} 2.4.4 r.8{tu 3} 0.2.8{tu 3} 3.2.8{tu 3} |\n0.2.4 0.2.8{tu 3} 3.2.8{tu 3} 0.1.8{tu 3} 2.4{slur s1}.8{d} 2.3.16 0.2{slur s1}.8{tu 3} 2.4.8{tu 3} 2.3.8{tu 3} |\n2.3.4 0.3.8{tu 3} 0.2.8{tu 3} 2.3{slur s2}.16{tu 3} 0.3{slur s2}.16{tu 3} 2.4.4 2.4{t}.8{tu 3} 0.4.8{tu 3} 4.4.8{tu 3}", "marks": [{"at": "Ô 2", "text": "Em → G"}, {"at": "Ô 3", "text": "Bm → Em"}, {"at": "Ô 4", "text": "G → Em"}, {"at": "Ô 5", "text": "Am → Em"}], "guidance": ["Đọc từng nốt: đây là nốt nào của G–Em, nằm ở dây nào, ngăn nào?", "Giai điệu nằm ở ngăn 0–4, dây 2–5: cùng một vùng đầu cần.", "Ô 4–5 có cung luyến: nốt luyến cùng dây thì chơi bằng luyến (Buổi 05)."]}, {"kind": "study", "title": "Chọn Bass theo hợp âm trong G–Em", "blocks": [{"b": "table", "rows": [["Hợp âm", "Bass gốc", "Bass quãng 5"], ["Em", "Mi — dây 6 buông", "Si — dây 5 ngăn 2"], ["G", "Sol — dây 6 ngăn 3", "Rê — dây 4 buông"], ["Bm", "Si — dây 5 ngăn 2", "Fa♯ — dây 6 ngăn 2"], ["Am", "La — dây 5 buông", "Mi — dây 6 buông"], ["D", "Rê — dây 4 buông", "La — dây 5 buông"], ["C", "Đô — dây 5 ngăn 3", "Sol — dây 6 ngăn 3"]]}, {"b": "ul", "items": ["Bass là nốt gốc hoặc quãng 5 của hợp âm, đặt ở phách 1 của ô.", "Nếu bass làm đứt câu hát hoặc tay trái không kịp, bỏ bass ở ô đó — giai điệu quan trọng hơn.", "Thêm bass xong, đàn thử cả hai: nốt giai điệu nào bị vướng thì tìm vị trí khác cho nốt đó (cùng nốt có thể bấm ở hai dây)."]}, {"b": "callout", "label": "NHỚ", "text": "Xếp ngón không phải việc tách riêng: mỗi lần thêm bass, hãy nhìn lại giai điệu."}]}, {"id": "7.2", "kind": "checkpoint", "title": "Bài trả 7.2 — Bass cho hợp âm Bm", "accepts": ["quiz"], "required": true, "quiz": {"mode": "single", "question": "Chọn nốt bass GỐC cho hợp âm Bm trong giọng Em.", "options": [{"id": "a", "text": "Fa♯ — dây 6 ngăn 2"}, {"id": "b", "text": "Rê — dây 4 buông"}, {"id": "c", "text": "Si — dây 5 ngăn 2"}, {"id": "d", "text": "Mi — dây 6 buông"}], "hint": "Gốc của Bm là Si. Fa♯ là quãng 5 của Bm."}}, {"kind": "note", "title": "Nhịp 3 · Chuẩn bị năng lực chuyển soạn", "text": "Buổi 08 bạn sẽ tự chuyển soạn một bản nhạc phôi: giai điệu → bass → lót. Hôm nay tập quy trình đó trên một ví dụ rất ngắn, rồi tự làm trên 2 ô của Thành Phố Buồn giọng Em. Ví dụ dưới đây chỉ để xem cách nghĩ, không phải bài mẫu của đề tốt nghiệp. Kết thúc nhịp: Bài trả 7.3 (video + chữ)."}, {"kind": "layers", "title": "Ví dụ: hai ô, ba bước", "lead": "Giai điệu là một nốt dài mỗi ô: Mi rồi Sol. Cả hai ô đều chỉ dùng dây buông hoặc ngăn thấp để tay dễ.", "layers": [{"label": "Bước 1 · Giai điệu", "what": "Mi (dây 1 buông) rồi Sol (dây 1 ngăn 3). Chưa thêm gì.", "tex": "\\ts 4 4\n.\n0.1.1 |\n3.1.1"}, {"label": "Bước 2 · Thêm Bass", "what": "Ô 1 hợp âm Em: bass gốc Mi (dây 6 buông). Ô 2 hợp âm G: bass gốc Sol (dây 6 ngăn 3). Giai điệu vẫn ở dây 1 nên tay trái không phải đổi.", "tex": "\\ts 4 4\n.\n(0.1 0.6).1 |\n(3.1 3.6).1"}, {"label": "Bước 3 · Chọn nốt lót", "what": "Si (dây 2 buông) thuộc cả Em và G, nằm giữa giai điệu và bass, lại là dây buông nên không cần thêm ngón. Một nốt lót là đủ.", "tex": "\\ts 4 4\n.\n(0.1 0.2 0.6).1 {ch \"Em\"} |\n(3.1 0.2 3.6).1 {ch \"G\"}", "current": true}], "note": "Cách nghĩ: giai điệu trước, bass theo hợp âm, lót là nốt thuộc hợp âm nằm giữa hai bè. Kiểm tra tay trái sau mỗi bước."}, {"kind": "study", "title": "Từ hai bè sang ba bè — nghĩ về xếp ngón", "blocks": [{"b": "ol", "items": ["Chọn vị trí cho giai điệu: cả câu nằm gọn trong một vùng thì tay đứng yên.", "Thêm bass: bass thường ở dây 4–6; kiểm tra tay trái có kịp với nốt giai điệu cùng lúc không.", "Thêm lót: chọn nốt thuộc hợp âm, ưu tiên dây buông hoặc nốt không cần thêm ngón.", "Nếu vướng, quay lại bước trước và đổi một chỗ (đổi dây của nốt, bỏ bớt lót, bỏ bass ô đó)."]}, {"b": "callout", "label": "NỐI SANG BUỔI 08", "text": "Ở Buổi 08 bạn nhận một tờ nhạc phôi (Diễm Xưa hoặc Thành Phố Buồn) và làm đúng ba bước này trên giấy, rồi đàn. Bản phôi Thành Phố Buồn của Buổi 08 ở giọng Am — thuộc bản đồ C–Am quen thuộc; Buổi 07 giúp bạn đọc được cả hai giọng. Thầy không cung cấp sẵn lời giải."}]}, {"id": "7.3", "kind": "checkpoint", "title": "Bài trả 7.3 — Ba bước trên 2 ô", "required": true, "accepts": ["video_link", "text"], "prompt": "Chọn 2 ô liên tiếp trong Thành Phố Buồn giọng Em (ô 2–5 ở trên). Trên giấy: ghi vị trí giai điệu (dây, ngăn), nốt bass theo hợp âm, và nếu muốn một nốt lót. Đàn thử từng bước: giai điệu, rồi giai điệu + bass, rồi thêm lót. Nộp: link video bạn đàn 2 ô đó, kèm vài dòng chữ: ‘Tôi chọn cách này vì…’. Không cần hoàn hảo; chơi chậm, đúng và rõ."}, {"kind": "assignment", "title": "Bài tập", "items": [{"label": "Bài 1.", "text": "Chơi âm giai G–Em lên/xuống 3 lần ở ♩ = 60, nói tên nốt, không chơi Fa tự nhiên."}, {"label": "Bài 2.", "text": "Tìm Fa♯ ở ba chỗ trên đàn (dây 1, dây 4, dây 6) và nói nó cao hơn Fa một ngăn."}, {"label": "Bài 3.", "text": "Đọc giai điệu Thành Phố Buồn giọng Em ô 1–5: nói tên từng nốt và vị trí."}, {"label": "Bài 4.", "text": "Với hợp âm Em, G, Bm, Am: chỉ đúng bass gốc và quãng 5 trên cần đàn."}, {"label": "Bài 5.", "text": "Làm 3 bước trên giấy cho 2 ô bạn chọn, rồi đàn và quay video cho Bài trả 7.3."}], "message": "Mang đúng chỗ còn vướng đến buổi học. Câu Thầy hỏi vẫn là: “Tại sao bạn chọn như vậy?”"}, {"kind": "checklist", "items": ["Tôi nói được G–Em chỉ khác C–Am ở Fa♯.", "Tôi tìm được 7 nốt G–Em ở đầu cần.", "Tôi chơi được âm giai G–Em và không nhầm Fa♯ với Fa.", "Tôi chọn được bass gốc hoặc quãng 5 cho Em, G, Bm, Am, D, C.", "Tôi tính lại xếp ngón khi thêm bass.", "⭐ Tôi nói được vì sao mình chọn vị trí và nốt như vậy."]}, {"kind": "studentNotes", "title": "Tôi chọn cách này vì…", "lines": 6}]$j$::jsonb, now());
  insert into public.class_checkpoint_keys (session_id, checkpoint_id, mode, correct) values
    ('97d1f3ec-d96d-4ce3-bc78-e7ad970fe50f', '7.1', 'single', array['b']),
    ('97d1f3ec-d96d-4ce3-bc78-e7ad970fe50f', '7.2', 'single', array['c'])
  on conflict (session_id, checkpoint_id) do nothing;
  update public.class_lesson_content set blocks = $j$[{"kind": "recap", "title": "Từ Buổi 06 – 07 sang Buổi 08", "steps": [{"label": "Melody", "items": ["Đọc nốt, chọn vùng đàn, xếp ngón tay trái (Buổi 01–04).", "Nốt ♯/♭ tìm từ nốt đã biết (Buổi 04)."]}, {"label": "Bass", "items": ["Chọn bass theo tên hợp âm: gốc hoặc quãng 5 (Buổi 02, 05).", "Nối nốt bằng gảy lại · trượt · luyến (Buổi 03, 05)."]}, {"label": "Chord / lót", "items": ["Thêm lót vào chỗ giai điệu ngân dài (Buổi 06).", "Buổi 07 bạn đã thực hành trên bài mẫu."]}], "message": "Buổi 08 không dạy kỹ thuật mới. Hôm nay bạn tự làm trọn một bản Solo Guitar trình độ 1 từ một tờ phôi."}, {"kind": "objectives", "title": "Cuối buổi, bạn làm được", "items": ["Nói được quy trình ba bè: Melody → Bass → Chord, và vì sao xếp ngón không tách rời.", "Tự chuyển soạn một bản nhạc phôi trên giấy theo ba bước.", "Đàn lần lượt Melody, Melody + Bass, rồi cả ba bè; sửa lại bản giấy cho khớp với bài đàn.", "⭐ QUAN TRỌNG NHẤT — Đạt ĐÚNG ở cả ba bè là đạt chuẩn tốt nghiệp Chặng 1. ĐẸP và ĐỘC ĐÁO là mức phát triển, không bắt buộc."]}, {"kind": "note", "title": "Nhịp 1 · Tổng kết quy trình", "text": "Một bản Solo Guitar là ba bè chồng lên nhau: Melody là bông hoa, Bass là cột nhà, Chord là lớp lót giữa hai bè. Thứ tự làm luôn là Melody trước, rồi Bass, rồi Chord. Mỗi lần thêm một bè, hãy quay lại xem bè trước còn đàn được không. Nếu không, sửa cách xếp ngón hoặc bỏ bớt phần phụ — Melody và Bass là phần không được mất. Kết thúc nhịp: Bài trả 8.1 (trắc nghiệm)."}, {"id": "8.1", "kind": "checkpoint", "title": "Bài trả 8.1 — Thêm Bass thì làm gì với Melody?", "accepts": ["quiz"], "required": true, "quiz": {"mode": "single", "question": "Khi đã chọn xong nốt Bass cho một ô nhịp, bước tiếp theo đúng nhất là gì?", "options": [{"id": "a", "text": "Giữ nguyên cách xếp ngón Melody, không cần xem lại."}, {"id": "b", "text": "Bỏ Melody ở ô đó, chỉ giữ Bass."}, {"id": "c", "text": "Tính lại cách xếp ngón để tay trái vừa chơi được Melody vừa chơi được Bass, sửa nếu cần."}, {"id": "d", "text": "Thêm ngay nốt đệm Chord rồi mới thử đàn."}], "hint": "Xếp ngón không phải công đoạn riêng: thêm Bass là phải kiểm tra lại Melody."}}, {"kind": "note", "title": "Nhịp 2 · Đề bài tốt nghiệp", "text": "Đề bài: tự chuyển soạn MỘT trong hai bản nhạc phôi thành Solo Guitar trình độ 1 — Diễm Xưa hoặc Thành Phố Buồn. Hai bài có giá trị ngang nhau; bạn chọn theo sở thích và khả năng, không cần làm cả hai. Bạn không học thuộc bản mẫu: bạn tự chọn phương án và giải thích được lựa chọn của mình. Tải tờ phôi bạn chọn, in ra A4 và làm bằng bút chì để dễ sửa. Kết thúc nhịp: Bài trả 8.2 (trắc nghiệm)."}, {"kind": "study", "title": "Giai đoạn 1 — Chuyển soạn trên giấy", "blocks": [{"b": "download", "title": "Bản nhạc phôi – Diễm Xưa (PDF A4)", "note": "Giọng Am, 25 ô nhịp, có khuông, TAB, lời ca và hợp âm Am · A7 · Dm · E của Thầy. Chưa có Bass, nốt đệm hay xếp ngón.", "label": "Tải bản nhạc phôi Diễm Xưa", "href": "https://wojmdilyflffvdtpovmq.supabase.co/storage/v1/object/public/lessons/solo01/chang1/diem-xua_ban-nhac-phoi_v1.pdf"}, {"b": "download", "title": "Bản nhạc phôi – Thành Phố Buồn (PDF A4)", "note": "Giọng Am (cùng giai điệu với Buổi 07, hạ xuống Am), 26 ô nhịp, có khuông, TAB và lời ca. Khung hợp âm xem ở bảng bên dưới. Chưa có Bass, nốt đệm hay xếp ngón.", "label": "Tải bản nhạc phôi Thành Phố Buồn", "href": "https://wojmdilyflffvdtpovmq.supabase.co/storage/v1/object/public/lessons/solo01/chang1/thanh-pho-buon_ban-nhac-phoi_v1.pdf"}, {"b": "callout", "label": "CHỌN MỘT BÀI", "text": "Chỉ cần tải và làm một tờ phôi. Cả hai bài đều chỉ có Melody; Bass, Chord và xếp ngón là việc của bạn."}, {"b": "h", "text": "Khung hợp âm — Diễm Xưa (giọng Am)"}, {"b": "table", "rows": [["Ô", "Hợp âm", "Ô", "Hợp âm", "Ô", "Hợp âm"], ["1", "Am", "2", "Am", "3", "Am → A7"], ["4", "Dm", "5", "Dm → Am", "6", "E"], ["7", "E", "8", "Am", "9", "Am → E"], ["10", "Am", "11", "Am → A7", "12", "Dm"], ["13", "Am → Dm", "14", "E", "15", "E"], ["16", "E", "17", "Am", "18", "Am → A7"], ["19", "Dm", "20", "Dm → Am", "21", "E"], ["22", "E", "23", "Am", "24", "Am → E"], ["25", "Am", "", "", "", ""]]}, {"b": "p", "text": "Hợp âm lấy từ bộ hợp âm đơn giản của Thầy cho Diễm Xưa (Am · A7 · Dm · E). Ô ghi hai hợp âm thì đổi theo thứ tự ghi; ô không ghi hợp âm mới giữ hợp âm ô trước."}, {"b": "h", "text": "Khung hợp âm — Thành Phố Buồn (giọng Am)"}, {"b": "table", "rows": [["Ô", "Hợp âm", "Ô", "Hợp âm", "Ô", "Hợp âm"], ["1", "Am", "2", "Am → C", "3", "Em → Am"], ["4", "C → Am", "5", "Dm → Am", "6", "G → Em"], ["7", "Em → G", "8", "Em → G", "9", "Am"], ["10", "Am", "11", "Am → Em", "12", "Am"], ["13", "C → Dm", "14", "F → Am", "15", "G → Em"], ["16", "G → Am", "17", "G → Em", "18", "Am"], ["19", "Am → C", "20", "Em → Am", "21", "C → Am"], ["22", "Dm → Am", "23", "G → Em", "24", "Em → G"], ["25", "Em → G", "26", "Am", "", ""]]}, {"b": "p", "text": "Khung hợp âm lấy từ bản hợp âm đã duyệt trong Thư viện Class (giọng Em), chuyển sang Am cùng với giai điệu (Em→Am, G→C, Bm→Em, Am→Dm, D→G, C→F). Ô ghi hai hợp âm thì đổi theo thứ tự ghi. Thầy chỉ cung cấp khung hợp âm, không cung cấp nốt Bass hay nốt đệm."}, {"b": "h", "text": "Bước 1 — MELODY"}, {"b": "ul", "items": ["Đọc cao độ và trường độ từng ô.", "Xác định vị trí từng nốt trên cần đàn (vùng, dây, ngăn).", "Đánh dấu kỹ thuật dự kiến: ép ngón, Slide, rung, luyến…", "Chưa cần phức tạp: ưu tiên ĐÚNG và chơi được."]}, {"b": "h", "text": "Bước 2 — BASS + XẾP NGÓN"}, {"b": "ul", "items": ["Ghi tên hợp âm theo khung hợp âm ở trên lên đầu mỗi ô của tờ phôi bạn chọn.", "Từ hợp âm, chọn nốt Bass và ghi vị trí (dây, ngăn) vào từng ô nhịp.", "Tính xếp ngón để chơi Melody và Bass cùng nhau; nếu vướng, quay lại sửa Melody.", "Có thể cân nhắc Bass lệch ở chỗ phù hợp, theo hướng dẫn của Thầy trên lớp."]}, {"b": "h", "text": "Bước 3 — CHORD + XẾP NGÓN"}, {"b": "ul", "items": ["Dựa trên khung Melody và Bass đã có, chọn nốt đệm thuộc hợp âm phù hợp.", "Ghi vị trí chèn: dây, ngăn, ngón tay.", "Bảo đảm cả ba bè chơi được cùng lúc.", "Đừng lạm dụng nốt đệm: rõ ràng và chơi được quan trọng hơn nhiều nốt."]}, {"b": "callout", "label": "LƯU Ý", "text": "Xếp ngón không phải công đoạn riêng. Mỗi lần thêm Bass hoặc Chord, hãy tính lại cách xếp ngón Melody nếu cần."}]}, {"kind": "score", "title": "Dạng tờ phôi — ví dụ từ Thành Phố Buồn ô 1–3", "subtitle": "Chỉ để xem dạng bản; không phải bài mẫu", "lead": "Ví dụ dạng bản phôi (lấy từ Thành Phố Buồn; Diễm Xưa có cùng dạng). Bass, hợp âm và kỹ thuật là phần bạn tự thêm; Thầy không cung cấp sẵn lời giải.", "tex": "\\ts 4 4\n\\lyrics 0 \"Thành phố nào _ Nhớ không em _ Nơi chúng mình tìm phút êm đềm Thành phố nào vừa đi đã mỏi _ _ Đường quanh co quyện gốc thông _ già _ Chiều đan tay nghe nắng chan _ hòa Nắng hôn nhẹ làm hồng môi em Mắt em buồn trong sương chiều anh thấy đẹp hơn Một sáng nhau Rồi từ đó _ vì cách xa _ duyên tình thêm nhạt nhòa Rồi từ đó _ trốn phong ba _ em làm dâu nhà người Âm thầm anh tiếc thương đời Đau buồn em khóc chia phôi Anh về gom góp kỷ niệm tìm vui Thành phố buồn _ lắm tơ vương _ cơn gió chiều lạnh buốt tâm hồn và con đường ngày xưa lá đổ _ _ Giờ không em sỏi đá u _ buồn _ Giờ không em hoang vắng phố _ phường Tiếng chuông chiều chầm chậm thê lương tiễn đưa người quên núi đồi quên cả tình yêu\"\n.\nr.8{tu 3} 2.3.8{tu 3} 0.1.8{tu 3} |\n\\ro 2.3.4 2.3{t}.8{tu 3} 0.1.8{tu 3} 3.2.8{tu 3} 1.2.4 1.2{t}.8{tu 3} 0.3.8{tu 3} 2.3.8{tu 3} |\n2.4.4 2.4.8{tu 3} 3.2.8{tu 3} 1.2.8{tu 3} 2.3.4 r.8{tu 3} 0.1.8{tu 3} 3.1.8{tu 3} |", "tempo": "Tempo: ♩ = 60", "guidance": ["Ô 1 là ô lấy đà (chưa đủ 4 phách).", "Dòng chữ dưới khuông là lời ca, giúp bạn nhận ra câu nhạc."]}, {"id": "8.2", "kind": "checkpoint", "title": "Bài trả 8.2 — Chuẩn tốt nghiệp", "accepts": ["quiz"], "required": true, "quiz": {"mode": "single", "question": "Theo đề tốt nghiệp Chặng 1, điều kiện để đạt chuẩn tốt nghiệp trình độ 1 là gì?", "options": [{"id": "a", "text": "Đạt mức ĐÚNG ở cả ba bè: Melody, Bass, Chord."}, {"id": "b", "text": "Dùng thật nhiều kỹ thuật trong bản chuyển soạn."}, {"id": "c", "text": "Chỉ cần Melody đúng, Bass và Chord để sau."}, {"id": "d", "text": "Phải đạt cả ĐÚNG, ĐẸP và ĐỘC ĐÁO ở cả ba bè."}], "hint": "ĐÚNG là chuẩn tốt nghiệp. ĐẸP và ĐỘC ĐÁO là mức phát triển cao hơn, không bắt buộc."}}, {"kind": "note", "title": "Nhịp 3 · Thực hành và hoàn thiện", "text": "Chuyển bản giấy lên đàn, rồi dùng chính bài đàn để kiểm tra bản giấy. Nếu thấy một chỗ không chơi được, sửa trên giấy rồi đàn lại — bản cuối phải thống nhất với bài đàn. Kết thúc nhịp: Bài trả 8.3 (bản giấy + video)."}, {"kind": "study", "title": "Giai đoạn 2 — Thực hành trên đàn và cách chấm", "blocks": [{"b": "ol", "items": ["Đàn Melody theo bản giấy, chậm và đều.", "Ghép Melody + Bass: mỗi lần chỉ thêm một ô hoặc một câu.", "Ghép Melody + Bass + Chord: bỏ nốt đệm nào làm Melody hoặc Bass bị yếu.", "Sửa bản giấy cho đúng với những gì bạn đàn được, rồi quay video."]}, {"b": "h", "text": "Hệ thống chấm 3Đ"}, {"b": "table", "rows": [["Bè", "ĐÚNG — chuẩn tốt nghiệp", "ĐẸP — chất lượng âm nhạc", "ĐỘC ĐÁO — sáng tạo"], ["Melody", "Đúng cao độ, trường độ, liền mạch.", "Dùng kỹ thuật để giai điệu mượt, tự nhiên, chân thực.", "Có lựa chọn hoặc xử lý riêng, hợp lý và chơi được."], ["Bass", "Đúng nốt, đúng vị trí, phối hợp được với Melody.", "Âm Bass ấm, rõ, cân đối; Bass lệch phù hợp.", "Có cách chọn Bass riêng, nói được vì sao."], ["Chord", "Đúng hòa âm, nốt đệm phù hợp, xếp ngón khả thi.", "Nốt đệm sạch, hòa với hai bè còn lại, xếp ngón thuận.", "Có cách chèn nốt đệm riêng, hợp lý về âm nhạc."]]}, {"b": "callout", "label": "NGUYÊN TẮC", "text": "Đạt ĐÚNG ở cả ba bè là đạt chuẩn tốt nghiệp Chặng 1. ĐẸP và ĐỘC ĐÁO là mức phát triển cao hơn, không bắt buộc, và không tính theo số lượng kỹ thuật. Thầy đối chiếu bản giấy với video cho từng bè."}]}, {"id": "8.3", "kind": "checkpoint", "title": "Bài trả 8.3 — Bài tốt nghiệp Chặng 1", "required": true, "accepts": ["video_link", "text"], "prompt": "Nộp ba phần. (1) Khai báo trong ô chữ: bạn chọn bài nào (Diễm Xưa hoặc Thành Phố Buồn). (2) Bản giấy: chụp ảnh hoặc xuất PDF tờ phôi đã hoàn thiện (Melody, Bass, nốt đệm, xếp ngón), tải lên Google Drive/iCloud/Google Photos ở chế độ ai có link đều xem được, rồi dán link vào ô chữ cùng vài dòng ‘Tôi chọn cách chuyển soạn này vì…’. (3) Video: dán link video bạn đàn đoạn Solo do chính mình chuyển soạn. Bản giấy và video phải thống nhất với nhau."}, {"kind": "assignment", "title": "Bài tập", "items": [{"label": "Bài 0.", "text": "Chọn MỘT bài (Diễm Xưa hoặc Thành Phố Buồn), tải tờ phôi và in ra."}, {"label": "Bài 1.", "text": "Làm Bước 1 trên giấy: đọc Melody, ghi vị trí và kỹ thuật dự kiến cho cả đoạn."}, {"label": "Bài 2.", "text": "Làm Bước 2: ghi hợp âm, nốt Bass và cách xếp ngón; đàn thử Melody + Bass."}, {"label": "Bài 3.", "text": "Làm Bước 3: chọn nốt đệm, ghép đủ ba bè; bỏ phần nào làm Melody hoặc Bass yếu."}, {"label": "Bài 4.", "text": "Đàn, quay video, sửa bản giấy cho khớp bài đàn, rồi nộp Bài trả 8.3."}], "message": "Không cần giống ai và không cần nhiều nốt. Cần đúng, chơi được, và bạn giải thích được lựa chọn của mình."}, {"kind": "checklist", "items": ["Tôi đã chọn một bài và tải đúng tờ phôi của bài đó.", "Tôi nói được thứ tự Melody → Bass → Chord.", "Tôi đã ghi Melody, Bass và nốt đệm lên tờ phôi.", "Tôi đã tính lại xếp ngón mỗi khi thêm bè.", "Tôi đàn được từng bước: Melody, rồi Melody + Bass, rồi ba bè.", "Bản giấy của tôi thống nhất với video.", "⭐ Tôi nói được vì sao mình chọn cách chuyển soạn này."]}, {"kind": "studentNotes", "title": "Tôi chọn cách chuyển soạn này vì…", "lines": 6}]$j$::jsonb, updated_at = now()
   where session_id = '949f1d47-1a70-423d-8f7b-7fdf86c233fd' and md5(blocks::text) = '435b2aa8cd571e763d3421914733b048' and jsonb_array_length(blocks) = 14;
